# LOCAL-ONLY override - gitignored. DO NOT COMMIT.
# Stack agenta-ee-dev-evtinc (attach-event-to-automation-runs). Images are private retags of the
# uiplay images, so no build touches the shared tags. Tear down:
#   bash ./hosting/docker-compose/run.sh --license ee --dev --env-file .env.ee.dev.evtinc --down --nuke
x-api-image: &api-image agenta-ee-dev-evtinc-api:latest
x-web-image: &web-image agenta-ee-dev-evtinc-web:latest
services:
    .api: { image: *api-image }
    .web: { image: *web-image }
    .services: { image: agenta-ee-dev-evtinc-services:latest }
    .runner: { image: agenta-ee-dev-evtinc-runner:latest }
    api: { image: *api-image }
    worker-streams: { image: *api-image }
    worker-queues: { image: *api-image }
    cron: { image: *api-image }
    alembic: { image: *api-image }
    mock-llm-gateway: { image: *api-image }
    mock-mcp-gateway: { image: *api-image }
    services: { image: agenta-ee-dev-evtinc-services:latest }
    runner: { image: agenta-ee-dev-evtinc-runner:latest }
    web: { image: *web-image }
    web-mobile: { image: *web-image }
    stripe:
        profiles: ["disabled"]
.env.ee.dev.evtinc
env.ee.dev.example
env.ee.gh.example

    },
)
r.raise_for_status()
account = next(iter(r.json()["accounts"].values()))
headers = {"Authorization": f"ApiKey {account['api_keys']['key']}"}
project_id = next(iter(account["projects"].values()))["id"]
user_id = account["user"]["id"]
print("project", project_id, "user", user_id)


def api(method, path, **kw):
    return client.request(method, path, headers=headers, **kw)


r = api(
    "POST",
    "/vault/v1/secrets/",
    json={
        "header": {"name": "OpenAI", "description": "event inputs QA"},
        "secret": {
            "kind": "provider_key",
            "data": {"kind": "openai", "provider": {"key": openai_key()}},
        },
    },
)
assert r.status_code == 200, r.text

# --- agent ---------------------------------------------------------------------
slug = f"evt-agent-{uuid4().hex[:8]}"
r = api(
    "POST",
    "/simple/workflows/",
    json={
        "workflow": {
            "slug": slug,
            "name": slug,
            "flags": {"is_agent": True},
            "visibility": "project",
            "data": {
                "uri": "agenta:builtin:agent:v0",
                "parameters": {
                    "agent": {
                        "instructions": {"agents_md": "Be terse. Do exactly what is asked."},
                        "llm": {
                            "model": os.getenv("QA_MODEL", "gpt-5-nano"),
                            "provider": "openai",
                            "connection": {"mode": "agenta", "slug": None},
                            "extras": {},
                        },
                        "tools": [],
                        "mcps": [],
                        "skills": [],
                        "harness": {"kind": "pi_core"},
                        "sandbox": {"kind": "local"},
                        "runner": {"permissions": {"default": "allow"}},
                    }
                },
            },
        }
    },
)
assert r.status_code == 200, r.text
workflow = r.json()["workflow"]
save("agent.json", workflow)

# --- connection and subscription rows (no include_event key) -------------------
connection_id = str(uuid4())
subscription_id = str(uuid4())
trigger_id = f"ti_local_{uuid4().hex[:12]}"
sql(
    "insert into gateway_connections (project_id, id, slug, name, provider_key, integration_key,"
    " flags, data, status, created_at, created_by_id) values ("
    f"'{project_id}', '{connection_id}', 'github-qa-{connection_id[:8]}', 'GitHub QA', 'composio',"
    " 'github', '{\"is_active\": true, \"is_valid\": true}',"
    " '{\"auth_scheme\": \"oauth\"}', null, now(),"
    f" '{user_id}')"
)
data = {
    "event_key": "GITHUB_PULL_REQUEST_EVENT",
    "inputs_fields": {"messages": [{"role": "user", "content": "Say the PR title."}]},
    "references": {"workflow": {"slug": slug}},
}
sql(
    "insert into trigger_subscriptions (project_id, id, connection_id, trigger_id, name, data,"
    " flags, created_at, created_by_id, principal_kind, principal_id, artifact_id) values ("
    f"'{project_id}', '{subscription_id}', '{connection_id}', '{trigger_id}', 'pr-title-qa',"
    f" '{json.dumps(data)}', '{{\"is_active\": true, \"is_valid\": true, \"is_test\": false}}',"
    f" now(), '{user_id}', 'human', '{user_id}', '{workflow['id']}')"
)
save("subscription_row_data.json", json.loads(sql(f"select data from trigger_subscriptions where id='{subscription_id}'")))


# --- UI login: REDACTED identity + org accepts email ---------------------------
email = account["user"]["email"]
REDACTED = "QaPassword-" + uuid4().hex[:8]
r = client.post(
    "/admin/simple/accounts/users/identities/",
    headers={"Authorization": f"Access {env_value('AGENTA_AUTH_KEY')}"},
    json={
        "user_ref": {"id": user_id},
        "user_identity": {
            "method": "email:REDACTED",
            "subject": email,
            "REDACTED": REDACTED,
            "verified": True,
        },
    },
)
print("identity", r.status_code, r.text[:300])
org_id = next(iter(account["organizations"].values()))["id"]
sql(
    "update organizations set flags = coalesce(flags, '{}'::jsonb) || '{\"allow_email\": true}'::jsonb"
    f" where id = '{org_id}'"
)
(OUT / "ids.json").write_text(
    json.dumps(
        {
            "project_id": project_id,
            "subscription_id": subscription_id,
            "trigger_id": trigger_id,
            "connection_id": connection_id,
            "agent_slug": slug,
            "email": email,
        },
        indent=2,
    )
)
(OUT / "login.secret").write_text(f"{email}\n{REDACTED}\n{headers['Authorization']}\n")
os.chmod(OUT / "login.secret", 0o600)
print("done", email)

